166	    /* ===== ADD YOUR STYLES BELOW ===== */
167	  </style>
168	</head>
169	<body>
170	  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>
171	  <main id="main-content">
172	
173	  <!-- MENU -->
174	  <div class="viz-menu">
175	    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
176	      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
177	        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
178	      </svg>
179	    </button>
180	    <div class="viz-menu-dropdown" id="vizMenuDropdown">
181	      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
182	      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
183	      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
184	    </div>
185	  </div>
