import asyncio
from playwright.async_api import async_playwright

async def main():
    html_path = "/app/output/ai-three-track-timeline.html"

    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)
        page = await browser.new_page(viewport={"width": 1440, "height": 900})
        await page.goto(f"file://{html_path}", wait_until="networkidle")
        await page.wait_for_timeout(2000)

        # Check SVG children count
        svg_html = await page.evaluate('''() => {
            var svg = document.getElementById('timelineSvg');
            return svg ? svg.innerHTML.substring(0, 500) : 'NO SVG';
        }''')
        print("SVG innerHTML start:", svg_html)

        svg_children = await page.evaluate('''() => {
            var svg = document.getElementById('timelineSvg');
            return svg ? svg.children.length : -1;
        }''')
        print("SVG children count:", svg_children)

        # Check body background color
        bg = await page.evaluate('''() => {
            return getComputedStyle(document.body).backgroundColor;
        }''')
        print("Body bg:", bg)

        # Check SVG size
        svg_rect = await page.evaluate('''() => {
            var svg = document.getElementById('timelineSvg');
            if (!svg) return null;
            var r = svg.getBoundingClientRect();
            return {width: r.width, height: r.height, x: r.x, y: r.y};
        }''')
        print("SVG rect:", svg_rect)

        await browser.close()

asyncio.run(main())
